BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L2 — Gift tax return filing deadline
(3, 'Estate and Gift Tax', 'Rivera gives her nephew $35,000 in cash on June 1, 2026. The annual exclusion is $19,000. By what date must Rivera file Form 709, Gift Tax Return, for 2026?', '["April 15, 2027", "October 15, 2027", "June 15, 2026", "December 31, 2026"]'::jsonb, 0, 'Under IRC Section 6075(b), a gift tax return (Form 709) is due on April 15 of the year following the calendar year in which the taxable gift was made. Because Rivera''s gift exceeded the $19,000 annual exclusion, she must file by April 15, 2027. Choice B is incorrect because October 15 is the extended due date and requires filing an extension—it is not the default deadline.', 'easy', 2),

-- Q2: medium / L3 — QTIP trust election effect on surviving spouse estate
(3, 'Estate and Gift Tax', 'Warren dies in 2026, leaving a $6,000,000 trust for his wife, Palmer. The trust pays all income to Palmer for life, with the remainder passing to Warren''s children. The executor elects QTIP treatment under Section 2056(b)(7). Analyze the effect of this election on Palmer''s future estate.', '["The trust assets are excluded from Palmer''s gross estate because the marital deduction was claimed", "Only the income Palmer received during her lifetime is included in her gross estate", "The trust assets are included in Palmer''s gross estate under Section 2044 at their date-of-death fair market value", "The QTIP election permanently eliminates transfer tax on the trust corpus"]'::jsonb, 2, 'Under IRC Section 2044, property for which a QTIP election was made under Section 2056(b)(7) is included in the surviving spouse''s gross estate at its date-of-death value. The marital deduction defers rather than eliminates estate tax because the trust corpus will be taxed when the surviving spouse dies. Choice A is incorrect because the QTIP election specifically requires inclusion in the surviving spouse''s estate as the cost of obtaining the initial marital deduction.', 'medium', 3),

-- Q3: easy / L1 — Future interest does not qualify for annual exclusion
(3, 'Estate and Gift Tax', 'Under IRC Section 2503(b), which type of gift does not qualify for the annual gift tax exclusion?', '["A gift of cash", "A gift of a future interest", "A gift of publicly traded stock", "A gift to a minor under UGMA"]'::jsonb, 1, 'Under IRC Section 2503(b), the annual exclusion applies only to gifts of present interests—those giving the donee an unrestricted right to immediate use, possession, or enjoyment. A future interest, such as a remainder interest in a trust, does not qualify because the donee cannot currently benefit from the property. Choice A is incorrect because cash is a present interest with immediate use and enjoyment.', 'easy', 1),

-- Q4: easy / L1 — General power of appointment definition
(3, 'Estate and Gift Tax', 'Under IRC Section 2041, what is a general power of appointment?', '["A power to appoint property only to charitable organizations", "A power limited to distributing principal for a beneficiary''s health and education", "A power held exclusively by an independent trustee", "A power exercisable in favor of the holder, the holder''s estate, the holder''s creditors, or creditors of the holder''s estate"]'::jsonb, 3, 'Under IRC Section 2041(b)(1), a general power of appointment is one exercisable in favor of the decedent, the decedent''s estate, the decedent''s creditors, or creditors of the decedent''s estate. Property subject to such a power is included in the holder''s gross estate. Choice B is incorrect because powers limited by ascertainable standards (health, education, maintenance, support) are specifically excluded from the definition of a general power under Section 2041(b)(1)(A).', 'easy', 1),

-- Q5: easy / L1 — Special use valuation under Section 2032A
(3, 'Estate and Gift Tax', 'What does IRC Section 2032A allow an executor to elect for qualifying real property?', '["Valuation at the property''s highest and best use", "Deferral of all estate tax for 15 years", "Valuation based on the property''s actual use in farming or a closely held business", "Exclusion of farm property from the gross estate"]'::jsonb, 2, 'Under IRC Section 2032A, an executor may elect to value qualifying real property used in farming or a closely held business at its current-use value rather than its highest-and-best-use fair market value. This election can reduce the gross estate significantly. Choice A is incorrect because Section 2032A provides an alternative to the default highest-and-best-use valuation that would otherwise apply under Section 2031.', 'easy', 1),

-- Q6: easy / L1 — Gift tax charitable deduction
(3, 'Estate and Gift Tax', 'Under IRC Section 2522, what is the gift tax charitable deduction?', '["An unlimited deduction for the full value of gifts to qualified charitable organizations", "A deduction limited to 60% of the value of gifts to qualified charities", "A deduction capped at $19,000 per charity per year", "A deduction available only for testamentary transfers to charity"]'::jsonb, 0, 'Under IRC Section 2522, a donor may claim an unlimited gift tax charitable deduction for the full value of gifts to qualified charitable, religious, scientific, and educational organizations. Unlike the income tax charitable deduction, there is no percentage-of-income limitation. Choice B is incorrect because the 60% limitation applies to income tax charitable deductions under Section 170, not to the gift tax charitable deduction under Section 2522.', 'easy', 1),

-- Q7: medium / L2 — Below-market gift loan under Section 7872
(3, 'Estate and Gift Tax', 'On January 1, 2026, Nakamura lends $200,000 to her adult child, Trent, at 0% interest. The applicable federal rate is 5%. Under IRC Section 7872, what is the deemed annual gift amount from Nakamura to Trent?', '["$0 — loans are not subject to gift tax", "$10,000 — the foregone interest for one year", "$19,000 — the full annual exclusion amount", "$200,000 — the entire loan principal"]'::jsonb, 1, 'Under IRC Section 7872, a below-market loan between family members is treated as a gift equal to the foregone interest—the difference between interest at the applicable federal rate and the rate charged. The deemed gift is $200,000 × 5% = $10,000 annually. Choice A is incorrect because Section 7872 recharacterizes the interest subsidy as a taxable gift even though the loan principal itself is not a transfer for gift tax purposes.', 'medium', 2),

-- Q8: hard / L3 — Transfers within 3 years of death (Section 2035)
(3, 'Estate and Gift Tax', 'Gallagher owned a $2,000,000 life insurance policy on her own life. On March 10, 2024, she transferred all incidents of ownership to an irrevocable life insurance trust. Gallagher died on January 5, 2026, less than three years after the transfer. Analyze the estate tax consequence under IRC Section 2035.', '["The policy proceeds are excluded because the transfer was completed and irrevocable", "Only the cash surrender value at the date of transfer is included in the gross estate", "The policy is excluded because transfers to irrevocable trusts are exempt from the three-year rule", "The $2,000,000 death benefit is included in the gross estate because the transfer occurred within three years of death"]'::jsonb, 3, 'Under IRC Section 2035(a), if a decedent transfers a life insurance policy (or any interest includable under Sections 2036–2042) within three years of death, the full death benefit is pulled back into the gross estate. Because Gallagher died within three years of transferring incidents of ownership, the entire $2,000,000 proceeds are included. Choice A is incorrect because Section 2035 specifically overrides the completed-transfer rule for life insurance and other Section 2036–2042 property transferred within three years of death.', 'hard', 3),

-- Q9: easy / L1 — Incidents of ownership under Section 2042
(3, 'Estate and Gift Tax', 'Under IRC Section 2042, what are incidents of ownership in a life insurance policy?', '["The right to receive dividends from the insurer", "The obligation to pay premiums on the policy", "Economic benefits such as the right to change beneficiaries, borrow against the policy, or surrender it", "The right to receive the death benefit as a named beneficiary"]'::jsonb, 2, 'Under IRC Section 2042, incidents of ownership include the right to change beneficiaries, surrender or cancel the policy, assign the policy, pledge it for a loan, or borrow against its cash value. Possessing any incident of ownership causes the policy proceeds to be included in the insured''s gross estate. Choice D is incorrect because being a named beneficiary alone does not constitute an incident of ownership held by the insured decedent.', 'easy', 1),

-- Q10: hard / L4 — Evaluate GRAT vs outright gift strategy
(3, 'Estate and Gift Tax', 'Prescott, age 65, wants to transfer $4,000,000 in appreciating real estate to her children while minimizing transfer taxes. Her CPA presents two options: (1) an outright gift using $4,000,000 of lifetime exemption, or (2) a two-year zeroed-out GRAT under Section 2702 with annuity payments that eliminate the taxable gift. Evaluate which strategy better preserves Prescott''s lifetime exemption.', '["The GRAT is superior because it transfers appreciation exceeding the Section 7520 hurdle rate to the children while consuming little or no lifetime exemption", "The outright gift is superior because it removes all future appreciation from the estate without trust complexity", "Both strategies produce identical transfer tax results because the unified credit applies equally", "The GRAT is inferior because retained annuity payments are included in Prescott''s gross estate at death"]'::jsonb, 0, 'Under IRC Section 2702, a GRAT''s taxable gift equals the value of the transferred property minus the present value of the retained annuity. A zeroed-out GRAT minimizes the taxable gift, preserving the donor''s lifetime exemption. If assets outperform the Section 7520 hurdle rate, the excess passes to the remaindermen transfer-tax-free. Choice B is incorrect because an outright gift consumes $4,000,000 of lifetime exemption, leaving less to shelter the donor''s estate at death.', 'hard', 4),

-- Q11: medium / L2 — Community property double step-up basis
(3, 'Estate and Gift Tax', 'Mitchell and Torres are married and reside in a community property state. They own community property stock with a combined basis of $100,000 and a fair market value of $600,000. Mitchell dies in 2026. Under Section 1014(b)(6), what is Torres''s basis in the entire stock after Mitchell''s death?', '["$100,000", "$300,000", "$600,000", "$350,000"]'::jsonb, 2, 'Under IRC Section 1014(b)(6), both halves of community property receive a stepped-up basis to fair market value when one spouse dies. Torres''s basis in the entire stock becomes $600,000—the full FMV at Mitchell''s death. Choice B is incorrect because it applies the step-up only to the decedent''s half, which is the rule for jointly held property in common-law states, not community property.', 'medium', 2),

-- Q12: medium / L3 — FLP valuation discount challenge analysis
(3, 'Estate and Gift Tax', 'Calloway transfers a 30% limited partnership interest in a family limited partnership holding $10,000,000 in marketable securities to her son. An appraiser applies a 25% combined discount for lack of marketability and minority interest. Analyze why the IRS might challenge this valuation under Section 2512.', '["The IRS will accept any discount supported by a qualified appraisal without challenge", "Section 2704 prohibits all valuation discounts for transfers between family members", "The IRS cannot challenge valuations if the donor files Form 709 with adequate disclosure", "The IRS may argue the discount is excessive because the underlying assets are liquid marketable securities rather than illiquid operating business interests"]'::jsonb, 3, 'Under IRC Section 2512, gifts are valued at fair market value, and the IRS closely scrutinizes valuation discounts on family limited partnerships holding liquid assets. Courts have reduced discounts when underlying assets are marketable securities rather than illiquid business interests. Choice B is incorrect because Section 2704(b) restricts certain applicable restrictions but does not categorically prohibit valuation discounts for family transfers.', 'medium', 3),

-- Q13: medium / L2 — Net gift calculation (donee pays gift tax)
(3, 'Estate and Gift Tax', 'Erickson makes a $500,000 gift to her friend Valdez in 2026, with the condition that Valdez pays the resulting gift tax of $80,000. Erickson has exhausted her lifetime exemption. Under the net gift doctrine (Rev. Rul. 75-72), what is the amount of Erickson''s taxable gift?', '["$500,000", "$580,000", "$420,000", "$400,000"]'::jsonb, 2, 'Under IRC Section 2512 and the net gift doctrine (Rev. Rul. 75-72), when a donee agrees to pay the gift tax, the taxable gift is reduced by the tax assumed. The taxable gift is $500,000 − $80,000 = $420,000 because the donor is relieved of the tax liability. Choice A is incorrect because it fails to reduce the gift by the tax obligation assumed by the donee, which is treated as consideration flowing back to the donor.', 'medium', 2),

-- Q14: easy / L1 — Applicable exclusion amount definition
(3, 'Estate and Gift Tax', 'What is the applicable exclusion amount under IRC Section 2010?', '["The maximum amount of taxable gifts allowed annually without filing Form 709", "The cumulative amount shielded from estate and gift tax by the unified credit", "The maximum estate tax rate applied to taxable estates above the threshold", "The amount of the marital deduction available to a surviving spouse"]'::jsonb, 1, 'Under IRC Section 2010, the applicable exclusion amount is the cumulative dollar amount of taxable transfers—both gifts and estate—that is sheltered from federal transfer tax by the unified credit. For 2026, this amount is approximately $14.50 million per individual. Choice A is incorrect because it describes the annual exclusion under Section 2503(b), which is a separate per-donee exclusion that does not reduce the lifetime exemption.', 'easy', 1),

-- Q15: medium / L2 — Section 6166 installment payment of estate tax
(3, 'Estate and Gift Tax', 'Bennett dies in 2026 with a $12,000,000 gross estate. A closely held business valued at $5,400,000 comprises 45% of the adjusted gross estate. The executor wants to defer estate tax under Section 6166. What is the maximum deferral period for estate tax attributable to the business interest?', '["5 years from the due date of the estate tax return", "10 years from the date of death with no interest", "15 years beginning on the date of the decedent''s death", "Up to 14 years: a 5-year deferral with interest-only payments followed by 10 annual installments"]'::jsonb, 3, 'Under IRC Section 6166, if a closely held business exceeds 35% of the adjusted gross estate, the executor may elect to defer the attributable estate tax for up to 5 years (interest only), then pay in up to 10 annual installments—a maximum of approximately 14 years from the return due date. Choice A is incorrect because it describes only the initial deferral period and omits the subsequent 10-year installment period permitted under Section 6166.', 'medium', 2),

-- Q16: hard / L4 — Evaluate completed gift vs incomplete gift timing
(3, 'Estate and Gift Tax', 'Spencer transfers $3,000,000 to a trust for her children but retains the power to change beneficiaries among her descendants. Two years later, Spencer releases the power when the trust is worth $3,800,000. Evaluate the gift tax consequences of Spencer''s actions.', '["No gift tax applies because Spencer originally retained control, making the entire arrangement tax-free", "The gift becomes taxable when Spencer releases the power, valued at the trust''s $3,800,000 fair market value on the release date", "The gift is taxable at the original $3,000,000 because the initial transfer date controls regardless of retained powers", "The trust assets are excluded from both gift and estate tax because Spencer created an irrevocable trust"]'::jsonb, 1, 'Under IRC Section 2511, a gift is not complete until the donor relinquishes dominion and control. Because Spencer retained the power to change beneficiaries, no completed gift occurred at the trust''s creation. When Spencer releases that power, the gift becomes complete and is valued at the trust''s $3,800,000 fair market value on the release date. Choice C is incorrect because gift tax valuation occurs when dominion and control are fully relinquished, not at the original funding date.', 'hard', 4),

-- Q17: medium / L3 — Adjusted taxable gifts effect on estate tax computation
(3, 'Estate and Gift Tax', 'Doyle made $2,000,000 in taxable gifts in 2020 and paid no gift tax due to the unified credit. Doyle dies in 2026 with a taxable estate of $10,000,000. Analyze how the 2020 gifts affect the estate tax computation under Section 2001.', '["The gifts are added as adjusted taxable gifts, increasing the tentative tax, but the gift tax credit used on those gifts is subtracted to prevent double taxation", "The gifts are ignored because gift tax was already addressed by the unified credit during Doyle''s lifetime", "The gifts reduce the taxable estate dollar-for-dollar because they were previously reported", "The gifts are included in the gross estate and taxed again at the estate tax rate"]'::jsonb, 0, 'Under IRC Section 2001(b), the estate tax is computed on the taxable estate plus adjusted taxable gifts. The tentative tax on this combined amount is then reduced by the gift tax that would have been payable on lifetime gifts. This mechanism pushes the estate into higher marginal brackets while preventing actual double taxation. Choice B is incorrect because Section 2001 requires adjusted taxable gifts to be added back, ensuring the cumulative progressive rate structure applies to all transfers.', 'medium', 3),

-- Q18: hard / L4 — Evaluate qualified disclaimer strategy
(3, 'Estate and Gift Tax', 'Knox, a wealthy widow with a $14,000,000 estate, inherits $8,000,000 from her deceased mother. Her CPA recommends a qualified disclaimer under Section 2518 so the assets bypass Knox and pass directly to Knox''s children. Evaluate whether the disclaimer achieves estate tax savings and identify the key compliance requirement.', '["The disclaimer is ineffective because disclaimed assets are treated as taxable gifts from Knox to her children", "The disclaimer keeps $8,000,000 out of Knox''s taxable estate, provided she disclaims within 9 months and has not accepted any benefit from the property", "The disclaimer must be filed within 12 months and requires probate court approval to be valid", "The disclaimer is effective only if Knox''s children are specifically named as contingent beneficiaries in the mother''s will"]'::jsonb, 1, 'Under IRC Section 2518, a qualified disclaimer must be irrevocable, in writing, delivered within 9 months of the transfer creating the interest, and the disclaimant must not have accepted any interest or benefit from the property. A qualified disclaimer is not treated as a transfer by the disclaimant for gift or estate tax purposes, so the $8,000,000 bypasses Knox''s estate. Choice A is incorrect because Section 2518 specifically provides that a qualified disclaimer is not treated as a taxable transfer by the disclaimant.', 'hard', 4),

-- Q19: medium / L3 — GST taxable distribution vs taxable termination
(3, 'Estate and Gift Tax', 'Thornburg created a trust for her child, Kimball, with remainder to Thornburg''s grandchild, Manning. In 2026, the trustee distributes $150,000 to Manning while Kimball still holds an income interest. Analyze whether this is a taxable distribution or taxable termination under IRC Chapter 13.', '["It is a taxable termination because trust assets are passing to a skip person", "It is neither because distributions to grandchildren are automatically exempt from GST tax", "It is a direct skip because the transfer goes directly from Thornburg to a skip person", "It is a taxable distribution because the distribution is made to a skip person while a non-skip person still holds an interest in the trust"]'::jsonb, 3, 'Under IRC Section 2612(b), a taxable distribution occurs when a distribution is made from a trust to a skip person while a non-skip person retains an interest. Because Kimball (non-skip) still holds an income interest, the $150,000 distribution to Manning (skip person) is a taxable distribution. Choice A is incorrect because a taxable termination under Section 2612(a) requires that all interests held by non-skip persons terminate, which has not occurred here since Kimball retains an interest.', 'medium', 3),

-- Q20: medium / L2 — Deduction for claims against the estate
(3, 'Estate and Gift Tax', 'Phillips dies in 2026 with a gross estate of $9,000,000. The estate owes $120,000 in medical bills incurred before death, $45,000 in state income taxes, and a $250,000 mortgage on estate property. Under Section 2053, what is the total deductible amount for claims against the estate?', '["$120,000", "$165,000", "$415,000", "$295,000"]'::jsonb, 2, 'Under IRC Section 2053(a)(3) and (a)(4), deductible claims against the estate include debts of the decedent enforceable at death and mortgages on estate property. The total is $120,000 (medical bills) + $45,000 (state income taxes) + $250,000 (mortgage) = $415,000. Choice D is incorrect because it excludes the medical bills, which are legitimate claims against the estate that were incurred before death and are fully deductible under Section 2053.', 'medium', 2),

-- Q21: medium / L2 — Section 2036 retained life estate inclusion
(3, 'Estate and Gift Tax', 'Orozco transfers her vacation home valued at $800,000 to an irrevocable trust in 2020 but retains the right to use the home each summer for the rest of her life. Orozco dies in 2026 when the home is worth $1,100,000. Under Section 2036, what amount is included in Orozco''s gross estate?', '["$0 because the irrevocable transfer was complete", "$800,000 — the value at the date of transfer", "$1,100,000 — the full date-of-death value", "$300,000 — only the post-transfer appreciation"]'::jsonb, 2, 'Under IRC Section 2036(a)(1), if a decedent transfers property but retains the right to possession, use, or enjoyment for life, the full date-of-death fair market value is included in the gross estate. Orozco''s retained summer use constitutes a retained life estate, so $1,100,000 is included. Choice A is incorrect because irrevocability of the trust does not prevent estate inclusion when the transferor retains possession or enjoyment under Section 2036.', 'medium', 2),

-- Q22: easy / L1 — Unified transfer tax system definition
(3, 'Estate and Gift Tax', 'What is the unified transfer tax system under federal tax law?', '["A system that taxes estates and gifts under separate rate schedules with independent exemptions", "A flat tax imposed only on transfers exceeding $5,000,000", "A system that exempts all inter vivos gifts from federal taxation", "A single progressive rate schedule and cumulative exemption applied to both lifetime gifts and transfers at death"]'::jsonb, 3, 'Under IRC Sections 2001 and 2502, the unified transfer tax system applies a single progressive rate schedule to the cumulative total of lifetime taxable gifts and testamentary transfers. A unified credit shelters a specified exclusion amount across both taxes. Choice A is incorrect because Congress unified the estate and gift tax systems in 1976, eliminating separate rate schedules and creating a single cumulative framework.', 'easy', 1),

-- Q23: hard / L4 — Evaluate FLP strategy risk under Section 2036
(3, 'Estate and Gift Tax', 'Hoffman, age 72, holds $12,000,000 in investment real estate. Her estate planner proposes transferring the real estate to a family limited partnership, then gifting 40% limited partnership interests to her children with combined valuation discounts of 35%. Her CPA warns about potential IRS challenges. Evaluate the primary transfer tax risk of this strategy.', '["The risk is minimal because all FLP discount strategies have been consistently upheld by the Tax Court", "The IRS may argue under Section 2036(a) that Hoffman retained economic benefit from partnership assets for personal use, causing full estate inclusion without discounts", "Section 2704 automatically eliminates all valuation discounts for family-controlled entities", "The only risk is that the IRS may slightly reduce the discount percentage while still allowing the FLP structure"]'::jsonb, 1, 'Under IRC Section 2036(a), the IRS has successfully challenged FLPs when the transferor retained possession, enjoyment, or economic benefit from the partnership assets—particularly when partnership income funded personal expenses or the transferor maintained effective control. Courts have included the full undiscounted value in the gross estate when Section 2036 applies. Choice C is incorrect because Section 2704(b) restricts certain applicable restrictions but does not categorically eliminate all valuation discounts for family entities.', 'hard', 4),

-- Q24: medium / L2 — Gift splitting requires both spouses to file Form 709
(3, 'Estate and Gift Tax', 'On July 4, 2026, Coleman gives $30,000 to his niece. Coleman''s spouse, Weston, did not make any gifts during 2026. They elect gift splitting under Section 2513. How many Form 709 returns must be filed for this election?', '["Two returns — both Coleman and Weston must each file Form 709 to consent to gift splitting", "One return — only the donor spouse, Coleman, must file", "No returns — the combined gift is below the couple''s combined annual exclusion", "One return — only the non-donor spouse, Weston, must consent in writing"]'::jsonb, 0, 'Under IRC Section 2513 and the Form 709 instructions, both spouses must file a gift tax return to elect gift splitting—even the non-donor spouse who made no independent gifts. Each spouse is treated as making $15,000 of the gift, and both must consent on their respective returns. Choice B is incorrect because the gift-splitting election requires the consent of the non-donor spouse, which is made by filing that spouse''s own Form 709.', 'medium', 2),

-- Q25: medium / L2 — Gift valuation date under Section 2512
(3, 'Estate and Gift Tax', 'On March 15, 2026, Pham gives her daughter 1,000 shares of Waverly Corp. stock. On the transfer date, the stock trades at $75 per share. By December 31, 2026, the stock has risen to $110 per share. Under Section 2512, at what value is the gift reported on Form 709?', '["$75,000", "$110,000", "$92,500", "$56,000"]'::jsonb, 0, 'Under IRC Section 2512(a), the value of a gift is determined at the date of the transfer to the donee. The gift is valued at $75 × 1,000 = $75,000, the fair market value on March 15, 2026. Subsequent appreciation belongs to the donee and is not reportable by the donor. Choice B is incorrect because year-end value is irrelevant; gift tax valuation occurs at the date of the completed transfer, not at a later measurement date.', 'medium', 2),

-- Q26: medium / L3 — Estate tax lien analysis under Section 6324
(3, 'Estate and Gift Tax', 'Reeves dies in 2026 owing federal estate tax. The executor distributes all estate assets to the beneficiaries before paying the tax. Analyze the IRS''s remedy under IRC Section 6324.', '["The IRS has no recourse once assets have been distributed to the beneficiaries", "Under Section 6324, a federal estate tax lien attaches to all gross estate assets for 10 years from the date of death, allowing the IRS to pursue the distributed property", "The IRS may only pursue the executor personally and cannot reach the distributed assets", "The estate tax lien expires upon distribution because the estate ceases to exist"]'::jsonb, 1, 'Under IRC Section 6324(a)(1), a special lien for estate tax attaches to all property included in the gross estate for 10 years from the date of death. This lien follows the property into the hands of beneficiaries, heirs, or transferees, giving the IRS recourse even after distribution. Choice C is incorrect because Section 6324 creates an in rem lien that follows the property itself, not merely a personal liability against the executor.', 'medium', 3),

-- Q27: hard / L4 — Evaluate QPRT strategy risk
(3, 'Estate and Gift Tax', 'Langley, age 60, owns a primary residence valued at $3,500,000. She proposes transferring it to a qualified personal residence trust with a 15-year retained term. If Langley survives the term, the home passes to her children at a deeply discounted gift tax value. Evaluate the primary risk if Langley does not survive the retained term.', '["The children must return the home to the estate and all gift tax previously paid is forfeited", "The home receives a stepped-up basis but provides no estate tax benefit because it was previously gifted", "The QPRT converts to a charitable remainder trust and the children receive nothing", "Under Section 2036, the entire date-of-death value of the home is included in Langley''s gross estate, negating the transfer tax benefit"]'::jsonb, 3, 'Under IRC Section 2036(a), if the grantor of a QPRT dies during the retained term, the full date-of-death fair market value of the residence is included in the grantor''s gross estate because the grantor retained the right to use the property. The estate tax benefit of the QPRT is completely negated—though the gift tax paid may generate a credit under Section 2001(b). Choice A is incorrect because the children do not return the home; rather, the estate receives a tax liability as if the transfer never occurred for estate tax purposes.', 'hard', 4),

-- Q28: medium / L3 — Annual exclusion inflation adjustment mechanism
(3, 'Estate and Gift Tax', 'Sandoval''s financial advisor notes that the annual gift tax exclusion increased from $15,000 in 2021 to $19,000 in 2026. Sandoval asks whether the exclusion can decrease in future years. Analyze the inflation adjustment mechanism under Section 2503(b).', '["The exclusion is indexed for inflation in $1,000 increments and can only increase or remain the same—it cannot decrease", "The exclusion resets to $10,000 whenever Congress amends the gift tax provisions", "The exclusion may decrease if the Consumer Price Index declines year over year", "The exclusion is permanently fixed by statute at $19,000 and does not adjust further"]'::jsonb, 0, 'Under IRC Section 2503(b)(2), the annual exclusion is adjusted for inflation in $1,000 increments using the Consumer Price Index, rounded down. Because the statute rounds down rather than adjusting continuously, the exclusion can only increase when inflation accumulates enough for a full $1,000 increment—it never decreases. Choice C is incorrect because the rounding mechanism prevents downward adjustments even if the CPI temporarily declines.', 'medium', 3),

-- Q29: medium / L3 — ILIT avoiding estate inclusion under Section 2042
(3, 'Estate and Gift Tax', 'Chambers, age 55, wants to purchase a $3,000,000 life insurance policy and ensure the death benefit is excluded from her gross estate. Her estate planner recommends an irrevocable life insurance trust (ILIT). Analyze what Chambers must avoid to prevent inclusion under Section 2042.', '["Chambers must avoid naming her spouse as a trust beneficiary to prevent marital deduction recapture", "Chambers must avoid paying premiums with her own funds to prevent constructive ownership", "Chambers must not retain any incidents of ownership, including the right to change beneficiaries, borrow against, or surrender the policy", "Chambers must avoid surviving more than three years after the trust is created"]'::jsonb, 2, 'Under IRC Section 2042, life insurance proceeds are included in the insured''s gross estate if the insured possesses any incidents of ownership at death—such as the power to change beneficiaries, borrow against, or surrender the policy. The ILIT must own all incidents from inception. Choice B is incorrect because premium payments by the insured do not by themselves create incidents of ownership; the IRS treats them as gifts to the trust, not as evidence of policy ownership.', 'medium', 3),

-- Q30: easy / L1 — Taxable termination definition under GST
(3, 'Estate and Gift Tax', 'Under IRC Chapter 13, what is a taxable termination for generation-skipping transfer tax purposes?', '["Any distribution from a trust to a beneficiary two or more generations below the transferor", "The termination of an interest in a trust such that only skip persons hold interests after the termination", "The death of any trust beneficiary regardless of remaining interests", "The revocation of a trust by the grantor during the grantor''s lifetime"]'::jsonb, 1, 'Under IRC Section 2612(a), a taxable termination occurs when an interest in a trust terminates (by death, lapse of time, or release) and afterward only skip persons hold interests in the trust. This triggers GST tax on the trust assets at the termination. Choice A is incorrect because it describes a taxable distribution under Section 2612(b), which occurs when property is distributed to a skip person while non-skip persons still hold trust interests.', 'easy', 1)
;

COMMIT;
